head.script:
        	scwin.count = 0;
			scwin.onpageload = function() {			
				scwin.count++;
				ui_wgc_main.addWidgets({
				    id : "widget"+scwin.count,
				    title : "위젯!!!"+scwin.count,
				    src : "widgetContainer_accessibility_userIconClass_WESD-1805_(WSQ-5873)_sub1.xml",
				    scope : true,
				    x : 0,
				    y : 0,
				    unitWidth : 1,
				    unitHeight : 1,
					userIconClass : "w2widget_title_imageIcon1"
				});		
				scwin.count++;
				ui_wgc_main.addWidgets({
				    id : "widget"+scwin.count,
				    title : "위젯위젯~~~~~~"+scwin.count,
				    src : "widgetContainer_accessibility_userIconClass_WESD-1805_(WSQ-5873)_sub2.xml",
				    scope : true,
				    x : 1,
				    y : 0,
				    unitWidth : 1,
				    unitHeight : 1,
					userIconClass : "w2widget_title_imageIcon2"
				});		
				scwin.count++;
				ui_wgc_main.addWidgets({
				    id : "widget"+scwin.count,
				    title : "위젯"+scwin.count,
				    src : "widgetContainer_accessibility_userIconClass_WESD-1805_(WSQ-5873)_sub3.xml",
				    scope : true,
				    x : 2,
				    y : 0,
				    unitWidth : 1,
				    unitHeight : 1,
					userIconClass : "w2widget_title_imageIcon3"
				});



				scwin.count++;
				ui_wgc_main2.addWidgets({
				    id : "widget"+scwin.count,
				    title : "위젯"+scwin.count,
				    src : "widgetContainer_accessibility_userIconClass_WESD-1805_(WSQ-5873)_sub1.xml",
				    scope : true,
				    x : 0,
				    y : 0,
				    unitWidth : 1,
				    unitHeight : 1,
					userIconClass : "w2widget_title_imageIcon4"
				});		
				scwin.count++;
				ui_wgc_main2.addWidgets({
				    id : "widget"+scwin.count,
				    title : "위젯"+scwin.count,
				    src : "widgetContainer_accessibility_userIconClass_WESD-1805_(WSQ-5873)_sub2.xml",
				    scope : true,
				    x : 1,
				    y : 0,
				    unitWidth : 1,
				    unitHeight : 1
				});		
				scwin.count++;
				ui_wgc_main2.addWidgets({
				    id : "widget"+scwin.count,
				    title : "위젯"+scwin.count,
				    src : "widgetContainer_accessibility_userIconClass_WESD-1805_(WSQ-5873)_sub3.xml",
				    scope : true,
				    x : 2,
				    y : 0,
				    unitWidth : 1,
				    unitHeight : 1
				});
			};
			scwin.onpageunload = function() {

			};

	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('ui_wgc_main_widget1_title_usericon') != null;
	}
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getDomById('ui_wgc_main_widget2_title_usericon') != null;
	}	
	scwin.checkVal3 = function() {
		return WebSquare.wUnit.getDomById('ui_wgc_main_widget3_title_usericon') != null;
	}	
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
